                   " E " +
                   "   ";
const int Xsize = 3, Ysize = 3;*/
//Console.ReadLine();

// коэффециент разряженности
double k = 0.0;

// приращение координат
int[,] delta = new int[,] { { 0, -1 }, { 1, 0 }, { 0, 1 }, { -1, 0 } };
int turtlesCount = 0;
int turnsCached = 0;
// лабиринт
dungeonCell[,] lab = new dungeonCell[Xsize, Ysize];
// координаты выхода
Cell exit = new Cell(0, 0);
// запонение лабиринта из текста
for (int y = 0; y < Ysize + 2; y++)
{
    for (int x = 0; x < Xsize; x++)
    {
        if (y < Ysize)
        {
            switch (labirinth[y * Xsize + x])
            {
                case '#':
                    lab[x, y] = new dungeonCell(new Cell(x, y), cellType.wall, -1, null, null, null, null);
                    break;
                case 'E':
                    exit = new Cell(x, y);
                    lab[x, y] = new dungeonCell(new Cell(x, y), cellType.exit, 0, null, new bool[] { false, false, false, false }, null, null);
                    break;
                default:
                    turtlesCount++;
                    lab[x, y] = new dungeonCell(new Cell(x, y), cellType.empty, -1, null, new bool[] { false, false, false, false }, null, null);
                    break;
            }
        }
        if (y - 2 >= 0 && y - 2 < Ysize)
        {
            var temp_wall = new bool[] { false, false, false, false };
            switch (labirinth[(y - 2) * Xsize + x])
            {
                case ' ':
                    int kc = 4;
                    for (int u = 0; u < 4; u++)
                    {
                        if (((y - 2 + delta[u, 1] < 0 || y - 2 + delta[u, 1] >= Ysize) ||
                            (x + delta[u, 0] < 0 || x + delta[u, 0] >= Xsize)) ||
                            ((y - 2 + delta[u, 1] >= 0 && y - 2 + delta[u, 1] < Ysize) &&
                            (x + delta[u, 0] >= 0 && x + delta[u, 0] < Xsize) &&
                            (lab[x + delta[u, 0], y - 2 + delta[u, 1]].ct == cellType.wall)))// ||
                                                                                             //lab[x + delta[u, 0], y - 2 + delta[u, 1]].ct == cellType.exit)))
                        {
                            lab[x, y - 2].walls[u] = true;
                            kc--;
                        }
                    }
                    k += kc;
                    break;
                default:
                    break;
            }
        }
    }
}
k /= turtlesCount;
// создание маршрутов обхода лабиринта
// запонение списка черепашек
List<dungeonCell> dc = new List<dungeonCell>();
Turtles prevTurtle = null;
Turtles startTurtle = null;
int turtlesId = 0;
for (int u = 0; u < 4; u++)
{
    if ((exit.y + delta[u, 1] >= 0 && exit.y + delta[u, 1] < Ysize) &&
        (exit.x + delta[u, 0] >= 0 && exit.x + delta[u, 0] < Xsize) &&
        lab[exit.x + delta[u, 0], exit.y + delta[u, 1]].ct == cellType.empty)
    {
        lab[exit.x + delta[u, 0], exit.y + delta[u, 1]].routeLen = 1;
        lab[exit.x + delta[u, 0], exit.y + delta[u, 1]].prevCell = lab[exit.x, exit.y];
        dc.Add(lab[exit.x + delta[u, 0], exit.y + delta[u, 1]]);
        Turtles turtles = new Turtles(turtlesId, lab[exit.x + delta[u, 0], exit.y + delta[u, 1]], prevTurtle, null);
        if (turtlesId == 0) startTurtle = turtles;
        else prevTurtle.next = turtles;
        prevTurtle = turtles;
        turtlesId++;
        lab[exit.x + delta[u, 0], exit.y + delta[u, 1]].turtle = turtles;
    }
}
while (dc.Count > 0)
{
    List<dungeonCell> tempDc = new List<dungeonCell>();
    foreach (dungeonCell dcValue in dc)
    {
        int xi = dcValue.coord.x;
        int yi = dcValue.coord.y;
        int routeLeni = dcValue.routeLen;
        for (int u = 0; u < 4; u++)
        {
            if (lab[xi, yi].walls[u] == false && lab[xi + delta[u, 0], yi + delta[u, 1]].routeLen < 0)
            {
                lab[xi + delta[u, 0], yi + delta[u, 1]].prevCell = lab[xi, yi];
                if (lab[xi + delta[u, 0], yi + delta[u, 1]].routeLen == -1) lab[xi + delta[u, 0], yi + delta[u, 1]].routeLen++;
                lab[xi + delta[u, 0], yi + delta[u, 1]].routeLen += 1 + lab[xi + delta[u, 0], yi + delta[u, 1]].prevCell.routeLen;
                tempDc.Add(lab[xi + delta[u, 0], yi + delta[u, 1]]);
                Turtles turtles = new Turtles(turtlesId, lab[xi + delta[u, 0], yi + delta[u, 1]], prevTurtle, null);
                prevTurtle.next = turtles;
                prevTurtle = turtles;
                turtlesId++;
                lab[xi + delta[u, 0], yi + delta[u, 1]].turtle = turtles;
            }
        }
    }
    dc = tempDc;
}

// основной цикл программы
// перебираем список черепашек
// пока он не окажется пуст
// применяем ко всем список команд
// и добавляем список команд каждой
// итерации к результирующему списку
int totalSteps = 0;
int totalcachedlen = 0;
int cc = 0;
int iter = 0;
Stopwatch sw = new Stopwatch();
sw.Restart();
List<Turn> resultCommands = new List<Turn>();
List<Turn> commands = new List<Turn>();
//goto nn1;
for (int xx = 0; xx < Xsize; xx++)
{
    commands.Add(Turn.down);
    //for (int xx = 0; xx < Xsize; xx++)
    commands.Add(Turn.right);
}
resultCommands.AddRange(commands);
ApplyCommands(commands);
nn1:;
//Turtles currTurtle = startTurtle;
while (startTurtle != null)
{
    iter++;
    commands = FindPath(startTurtle);
    ApplyCommands(commands);
    resultCommands.AddRange(commands);
}
Console.WriteLine("Time find = {0}", sw.ElapsedMilliseconds);
Console.WriteLine("Commands = {0}, Total steps = {1}, Turns cached = {2}({4}), Leaves = {3}, Iter = {5}", resultCommands.Count, totalSteps, turnsCached, cc, totalcachedlen, iter);
Console.WriteLine("K = {0}", k);
//TestCommands();
Console.WriteLine("Time test = {0}", sw.ElapsedMilliseconds);
// применяем список команд ко всем черепашкам
// удаляем черепашки, ушедший через выход
// а так же те, которые после перемещения
// остались на одной клетке
void ApplyCommands(List<Turn> commands)
{
    for (Turtles cT = startTurtle; cT != null; cT = cT.next)
    {
        // запоминаем откуда текущая черепашка начала движение
        Cell old_coor = new Cell(cT.cell.coord.x, cT.cell.coord.y);
        // запоминаем её ID
        //int old_id = cT.id;
        int ccount = 0;
        // запускаем цикл со всеми командами
        foreach (var c in commands)
        {
            totalSteps++;
            ccount++;
            // декодируем одну команду
            int u = DecodeTurn(c);
            // если упёрлись в стену, то ничего не делаем
            if (cT.cell.walls[u]) continue;
            // если дошли до выхода
            if (lab[cT.cell.coord.x + delta[u, 0], cT.cell.coord.y + delta[u, 1]].ct == cellType.exit)
            {
                // три следующие строки удаляют черепашку из списка
                // и обновляют первую черепашку если это требуется
                if (cT.prev != null) cT.prev.next = cT.next;
                else startTurtle = cT.next;
                if (cT.next != null) cT.next.prev = cT.prev;
                // так как у нас взаимосвязаны как данные в лабиринте,
                // так и у черепашек, то нужно из клетки лабиринта убрать
                // черепашку после её ухода из лабиринта, но только в том случае
                // если в стартовой клетке уже не стоит другая черепашка
                if (lab[old_coor.x, old_coor.y].turtle != null && lab[old_coor.x, old_coor.y].turtle.id == cT.id)
                    lab[old_coor.x, old_coor.y].turtle = null;
                if (ccount < commands.Count) cc++;
                goto exit;
            }
            // если мы не попали на выход то меняем приписку
            // у текущей черепушки на новую клетку в лабиринте
            cT.cell = lab[cT.cell.coord.x + delta[u, 0], cT.cell.coord.y + delta[u, 1]];
        }
        // сюда мы попадаем если все команды применены, но черепашка не вышла из лабиринта
        // здесь мы так же удаляем её из стартовой позиции, но только при совпадении таких условий:
        // 1. В клетке есть ссылка на черепашку
        // 2. ID черепашки соответствует текущей
        // 3. И текущие координаты не совпадают со стартовыми
        // Для 3-го пунта понятно что черепашка в результате скитаний могла вернуться
        if (lab[old_coor.x, old_coor.y].turtle != null && lab[old_coor.x, old_coor.y].turtle.id == cT.id &&
          (old_coor.x != cT.cell.coord.x || old_coor.y != cT.cell.coord.y))
            lab[old_coor.x, old_coor.y].turtle = null;

        // здесь как раз основное место применения ID черепашек
        // мы удаляем черепашку если её путь закончился на клетке
        // где уже стоит черепашка с МЕНЬШИМ id
        // если же нет, то мы эту черепашку привязываем к коетке лабиранта
        if (cT.cell.turtle != null && cT.id > cT.cell.turtle.id)
        {
            if (cT.prev != null) cT.prev.next = cT.next;
            else startTurtle = cT.next;
            if (cT.next != null) cT.next.prev = cT.prev;
        }
        else
            cT.cell.turtle = cT;
        exit:;
    }
}
// декодирование хода
int DecodeTurn(Turn t)
{
    switch (t)
    {
        case Turn.up: return 0;
        case Turn.right: return 1;
        case Turn.down: return 2;
        default: return 3;
    }
}
// построение маршрута для черепашки t
List<Turn> FindPath(Turtles t)
{
    // используем кеш, если он есть
    if (t.cell.turns != null)
    {
        turnsCached++;
        totalcachedlen += t.cell.turns.Count;
        return t.cell.turns;
    }
    var result = new List<Turn>();
    dungeonCell startDc = t.cell;
    result.Add(decodeOneCommand(startDc));
    startDc = startDc.prevCell;
    while (startDc.ct != cellType.exit)
    {
        result.Add(decodeOneCommand(startDc));
        startDc = startDc.prevCell;
    }
    t.cell.turns = result;
    return result;
}
// декодирование одной команды
Turn decodeOneCommand(dungeonCell dc)
{
    if (dc.coord.x == dc.prevCell.coord.x) // up or down
    {
        if (dc.coord.y < dc.prevCell.coord.y) // down
            return Turn.down;
        return Turn.up;
    }
    else // left or right
    {
        if (dc.coord.x < dc.prevCell.coord.x) // right
            return Turn.right;
        return Turn.left;
    }
}
// проверка команд
void TestCommands()
{
    for (int y = 0; y < Ysize; y++)
    {
        for (int x = 0; x < Xsize; x++)
        {
            if (lab[x, y].ct == cellType.empty)
            {
                ApplyTestCommands(resultCommands, x, y);
            }
        }
    }

}
// применение команд
void ApplyTestCommands(List<Turn> commands, int x, int y)
{
    foreach (var c in commands)
    {
        int u = DecodeTurn(c);
        if (lab[x, y].walls[u]) continue;
        if (lab[x + delta[u, 0], y + delta[u, 1]].ct == cellType.exit)
            return;
        x += delta[u, 0];
        y += delta[u, 1];
    }
    Console.ForegroundColor = ConsoleColor.DarkRed;
    Console.WriteLine("!!! ERROR !!!");
    Console.ResetColor();
}
void PrintLab(bool fast = false)
{
    for (int y = 0; y < Ysize; y++)
    {
        for (int x = 0; x < Xsize; x++)
        {
            if (fast && lab[x, y].ct == cellType.empty)
            {
                Console.SetCursorPosition(x, y);
                if (lab[x, y].routeLen < 1) Console.Write(" ");
                else Console.Write(".");
            }
            else
            {
                Console.SetCursorPosition(x, y);
                switch (lab[x, y].ct)
                {
                    case cellType.wall:
                        Console.Write("▓");
                        break;
                    case cellType.exit:
                        Console.Write("E");
                        break;
                    default:
                        if (lab[x, y].routeLen < 1) Console.Write(" ");
                        else Console.Write(".");
                        break;
                }
            }
        }
    }
    Console.SetCursorPosition(0, Ysize);
    Console.Out.Flush();
}
void PrintLab2()
{
    for (int y = 0; y < Ysize; y++)
    {
        for (int x = 0; x < Xsize; x++)
        {
            if (lab[x, y].ct == cellType.empty)
            {
                for (int u = 0; u < 4; u++)
                {
                    if ((y + delta[u, 1] >= 0 && y + delta[u, 1] < Ysize) &&
                        (x + delta[u, 0] >= 0 && x + delta[u, 0] < Xsize) &&
                        lab[x, y].walls[u] == true)
                    {
                        Console.SetCursorPosition(x + delta[u, 0], y + delta[u, 1]);
                        Console.Write("▓");
                    }
                }
            }
        }
    }
    Console.SetCursorPosition(0, Ysize);
    Console.Out.Flush();
}
public record Cell(int x, int y);
public enum Turn { up = 0, right = 1, down = 2, left = 3 };
public enum cellType { exit = -1, empty = 0, wall = 9 };
public class Turtles
{
    public Turtles prev { get; set; }
    public Turtles next { get; set; }
    public int id { get; set; }
    public dungeonCell cell { get; set; }
    public Turtles(int id, dungeonCell c, Turtles p, Turtles n)
    {
        this.id = id;
        cell = c;
        prev = p;
        next = n;
    }
}
public class dungeonCell
{
    public Turtles turtle { get; set; }
    public Cell coord { get; set; }
    public cellType ct { get; set; }
    public int routeLen { get; set; }
    public bool[] walls { get; set; }
    public dungeonCell prevCell { get; set; }
    public List<Turn> turns { get; set; }
    public dungeonCell(Cell c, cellType ct2, int rl, dungeonCell nc, bool[] w, List<Turn> t, Turtles tu)
    {
        coord = c;
        ct = ct2;
        routeLen = rl;
        prevCell = nc;
        walls = w;
        turns = t;
        turtle = tu;
    }
};